import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdir, writeFile, readFile, chmod } from 'node:fs/promises';
import path from 'node:path';
import { ensureSharedStatic } from '../../dist/shared-static.js';
import { StateStore } from '../../dist/state.js';
import { getPaths } from '../../dist/paths.js';
import { NectarService } from '../../dist/service.js';
import { spawnDetached, stopEnvGroup, pidAlive, ownershipRefusal } from '../../dist/commands.js';
const root = path.resolve(process.argv[2] ?? `.audit/T19/ownership-${Date.now()}`);
await mkdir(root, { recursive: true });
const state = path.join(root, 'state');
process.env.NECTAR_HOME = state;
process.env.NECTAR_SOCKET = path.join(root, 'unused.sock');
const lookup = path.join(root, 'lookup');
await writeFile(lookup, '#!/bin/sh\nprintf \'{"state":"terminal"}\\n\'\n');
await chmod(lookup, 0o700);
process.env.NECTAR_PROOF_LOOKUP = lookup;
const service = new NectarService(state);
await service.store.init();
await service.store.writeConfig({ ...await service.store.readConfig(), daemon: 'disabled', upstream_port_start: 27100, upstream_port_end: 27299, tailnet_port_start: 27300, tailnet_port_end: 27499, pack_server_port: 27099 });
const repo = path.join(root, 'repo');
await mkdir(repo);
const git = (...args) => execFileSync('git', args, { cwd: repo, stdio: 'pipe' });
git('init', '-b', 'main'); git('config', 'user.email', 'fixture@example.invalid'); git('config', 'user.name', 'Fixture');
await writeFile(path.join(repo, 'nectar.toml'), 'name = "ownership"\n[web]\nserve = "node server.mjs & exit 0"\nready_timeout = "5s"\n');
await writeFile(path.join(repo, 'server.mjs'), 'import http from "node:http";http.createServer((q,r)=>r.end("owned")).listen(Number(process.env.PORT),"127.0.0.1");');
git('add', '.'); git('commit', '-m', 'Ownership fixture');
const records = [];
const decoy = spawnDetached('exec sleep 300', root, process.env, path.join(root, 'decoy.log'));
const say = x => console.log(JSON.stringify(x));
const publish = async branch => { git('branch', branch); const p = await service.publish({ repo, branch, local: true }); const r = await service.store.readEnv(p.env); records.push(r); assert.equal(await (await fetch(r.urls.local)).text(), 'owned'); assert(r.serve.start_time); assert.equal(ownershipRefusal(r.serve), undefined); return r; };
try {
  const wrapped = await publish('wrapped');
  await service.stop(wrapped.name); assert(!pidAlive(wrapped.serve.pid));
  say({ backgroundWrapper: 'leader retained; stop killed runtime', pid: wrapped.serve.pid });
  const candidate = await publish('decoy');
  await stopEnvGroup(candidate.serve);
  const injected = { ...candidate.serve, ...decoy, start_time: 'stale-start' };
  await service.store.updateEnv(candidate.name, r => { r.serve = injected; r.proof_terminal_since = new Date(Date.now() - 26 * 3600000).toISOString(); });
  await assert.rejects(service.stop(candidate.name), /process start time differs/);
  let gc = await service.gc(); assert(gc.skipped.some(x => x.env === candidate.name && x.reason.includes("process start time differs"))); assert(pidAlive(decoy.pid));
  const doctor = await service.doctor({ fix: true, noDaemon: true });
  assert(doctor.checks.some(x => x.name === 'process-ownership' && x.details.some(d => d.env === candidate.name)));
  assert(pidAlive(decoy.pid)); assert.deepEqual((await service.store.readEnv(candidate.name)).serve, injected);
  say({ staleStart: 'stop, gc reap and doctor --fix refused', decoyAlive: true, recordPreserved: true });
  await service.store.updateEnv(candidate.name, r => { delete r.serve.start_time; });
  await assert.rejects(service.stop(candidate.name), /no process start time/);
  gc = await service.gc(); assert(gc.skipped.some(x => x.env === candidate.name && x.reason.includes("no process start time"))); assert(pidAlive(decoy.pid));
  const cluster = path.join(state, 'pg', '99');
  await mkdir(path.join(cluster, 'data'), { recursive: true });
  await writeFile(path.join(cluster, 'data', 'postmaster.pid'), String(decoy.pid));
  await writeFile(path.join(cluster, 'cluster.json'), JSON.stringify({ port: 27500 }));
  const legacyDoctor = await service.doctor({ noDaemon: true });
  assert(legacyDoctor.checks.find(x => x.name === 'dependency-ownership').details.some(d => d.major === 99 && d.hint.includes('pg_ctl stop')));
  say({ legacyLocalCluster: 'doctor warns with manual recovery guidance' });
  const sharedStore = new StateStore(getPaths(path.join(root, 'shared-legacy')));
  await sharedStore.init();
  const sharedFile = path.join(sharedStore.paths.root, 'shared-static.json');
  const sharedLegacy = JSON.stringify({ pid: decoy.pid, port: 27501, secret: 'fixture-only' });
  await writeFile(sharedFile, sharedLegacy);
  await assert.rejects(ensureSharedStatic(sharedStore), /no dedicated process group/);
  assert.equal(await readFile(sharedFile, 'utf8'), sharedLegacy);
  assert(pidAlive(decoy.pid));
  say({ legacySharedStatic: 'refused; metadata and decoy preserved' });
  const legacy = legacyDoctor.checks.find(x => x.name === 'process-ownership').details.find(d => d.env === candidate.name);
  assert(legacy.hint.includes(String(decoy.pid)));
  say({ legacy: 'refused and doctor gives manual recovery guidance', decoyAlive: true });
  await service.store.updateEnv(candidate.name, r => { r.serve = candidate.serve; });
  const reaped = await publish('reap');
  await service.store.updateEnv(reaped.name, r => { r.proof_terminal_since = new Date(Date.now() - 26 * 3600000).toISOString(); });
  gc = await service.gc(); assert(gc.transitions.some(x => x.env === reaped.name && x.action === 'reap')); assert(!pidAlive(reaped.serve.pid)); assert(!await service.store.maybeEnv(reaped.name));
  say({ ownedGcReap: 'stopped and removed', pid: reaped.serve.pid });
  const fixed = await publish('doctor');
  await service.store.updateEnv(fixed.name, r => { r.proof_terminal_since = new Date(Date.now() - 26 * 3600000).toISOString(); });
  await service.doctor({ fix: true, noDaemon: true }); assert(!pidAlive(fixed.serve.pid)); assert(!await service.store.maybeEnv(fixed.name));
  say({ ownedDoctorFix: 'stopped and removed', PASS: true });
} finally {
  await stopEnvGroup(decoy);
  const config = await service.store.readConfig();
  if (config.pack_server_pid && config.pack_server_start_time) await stopEnvGroup({ pid: config.pack_server_pid, pgid: config.pack_server_pgid, start_time: config.pack_server_start_time });
  for (const r of records) { if (await service.store.maybeEnv(r.name)) { await service.store.updateEnv(r.name, current => { current.serve = r.serve; }); await service.stop(r.name); } }
}
